import torch
import torch.nn as nn

# ----------------------------------------------------------------------
# PTX source for GELU (exact definition: x * 0.5 * (1 + erf(x / sqrt(2))))
# All inputs/outputs are fp16. Computation is performed in fp32.
# ----------------------------------------------------------------------
PTX_SOURCE = r'''
.version 7.0
.target sm_80
.address_size 64

.visible .entry gelu_kernel(
    .param .u64 input_ptr,
    .param .u64 output_ptr,
    .param .u64 N
)
{
    .reg .pred   %p;
    .reg .u64    %input, %output, %N;
    .reg .u32    %tid, %blockIdx, %blockDim, %gridDim;
    .reg .u64    %tid64, %blockIdx64, %blockDim64, %gridDim64;
    .reg .u64    %idx, %stride;
    .reg .u16    %h;
    .reg .f16    %h_out;
    .reg .f32    %x, %c0, %c1, %c2, %c3, %y;
    .reg .u64    %addr_tmp;

    // Load kernel parameters
    ld.param.u64 %input,  [input_ptr];
    ld.param.u64 %output, [output_ptr];
    ld.param.u64 %N,      [N];

    // Built‑in thread identifiers
    mov.u32 %tid,      %tid.x;
    mov.u32 %blockIdx, %ctaid.x;
    mov.u32 %blockDim, %ntid.x;
    mov.u32 %gridDim,  %nctaid.x;

    // Convert to 64‑bit for arithmetic
    cvt.u64.u32 %tid64,      %tid;
    cvt.u64.u32 %blockIdx64, %blockIdx;
    cvt.u64.u32 %blockDim64, %blockDim;
    cvt.u64.u32 %gridDim64,  %gridDim;

    // Global thread id = blockIdx * blockDim + tid
    mad.lo.u64 %idx, %blockIdx64, %blockDim64, %tid64;

    // stride = gridDim * blockDim
    mul.lo.u64 %stride, %gridDim64, %blockDim64;

    // If thread id exceeds N, skip execution
    setp.ge.u64 %p, %idx, %N;
    @%p bra DONE;

LOOP:
    // Compute byte address of the current element (half = 2 bytes)
    mul.lo.u64 %addr_tmp, %idx, 2;
    add.u64    %addr_tmp, %input, %addr_tmp;
    ld.global.u16 %h, [%addr_tmp];

    // Convert half -> float
    cvt.f32.f16 %x, %h;

    // x / sqrt(2)  (multiply by 1/sqrt(2))
    mul.f32 %c0, %x, 0.7071067811865475;   // 1/sqrt(2)

    // erf(x / sqrt(2)) – using the PTX approximation
    erf.approx.f32 %c1, %c0;

    // y = 0.5 * x * (1 + erf)
    add.f32 %c2, %c1, 1.0;
    mul.f32 %c3, %c2, %x;
    mul.f32 %y,  %c3, 0.5;

    // Convert back to half and store
    cvt.f16.f32 %h_out, %y;
    add.u64 %addr_tmp, %output, %addr_tmp;
    st.global.u16 [%addr_tmp], %h_out;

    // Advance to next element handled by this thread
    add.u64 %idx, %idx, %stride;
    setp.lt.u64 %p, %idx, %N;
    @%p bra LOOP;

DONE:
    ret;
}
'''

# ----------------------------------------------------------------------
# Model wrapper that loads the PTX kernel and launches it.
# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        # ptx_load is provided by the harness
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_contiguous()
        assert x.dtype == torch.float16

        out = torch.empty_like(x)

        # total number of elements
        N = x.numel()

        # launch configuration: 256 threads per block
        block = 256
        grid = (N + block - 1) // block

        # ptx_launch is provided by the harness
        # args must be a list of 64‑bit integers (pointers and size)
        args = [x.data_ptr(), out.data_ptr(), N]
        ptx_launch(self.module, "gelu_kernel",
                   (grid, 1, 1), (block, 1, 1), args)

        return out
